<template>
    <div class="ma-panel"><div class="ma-panel-head"><div><h2>Activity & Audit</h2><p class="ma-muted">Who changed mobile accounts, seats, settings, and published content, with recorded reasons.</p></div></div><MobileFilters id="ma-activity" v-model="filters" :options="options" dates search="Action or subject ID" :busy="loading" @apply="load(1,true)" />
        <div v-if="error" class="ma-error m-3" role="alert">{{ error }} <button class="btn btn-outline-danger btn-sm ml-2" @click="load()">Retry</button></div>
        <div class="ma-table-wrap"><table class="ma-table"><thead><tr><th>When</th><th>Staff member</th><th>Action</th><th>Subject</th><th>Reason</th><th>Changes</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="ma-empty" role="status">Loading activity…</td></tr><template v-else><tr v-for="entry in items" :key="entry.id"><td>{{ time(entry.created_at) }}</td><td>{{ entry.actor_name || 'System' }}</td><td>{{ label(entry.action) }}</td><td>{{ label(entry.subject_type) }}<small>#{{ entry.subject_id || '—' }}</small></td><td>{{ entry.reason || '—' }}</td><td><button v-if="entry.changes" class="btn btn-outline-secondary btn-sm" @click="selected=entry">View changes</button><span v-else>—</span></td></tr><tr v-if="!items.length && !error"><td colspan="6" class="ma-empty"><i class="fas fa-history"></i>No activity matches these filters.</td></tr></template></tbody></table></div><MobilePagination :pagination="pagination" :busy="loading" @change="load" />
        <MobileDialog v-if="selected" title="Audit record" @close="selected=null"><dl class="ma-details"><div><dt>Staff member</dt><dd>{{ selected.actor_name || 'System' }}</dd></div><div><dt>When</dt><dd>{{ time(selected.created_at) }}</dd></div><div><dt>Action</dt><dd>{{ label(selected.action) }}</dd></div><div><dt>Subject</dt><dd>{{ label(selected.subject_type) }} #{{ selected.subject_id || '—' }}</dd></div></dl><p class="ma-note">{{ selected.reason || 'No reason recorded.' }}</p><h3>Recorded changes</h3><pre class="ma-audit-json">{{ JSON.stringify(selected.changes,null,2) }}</pre><button class="btn btn-outline-secondary" @click="selected=null">Close</button></MobileDialog>
    </div>
</template>
<script>
import MobileFilters from './MobileFilters.vue';import MobilePagination from './MobilePagination.vue';import MobileDialog from './MobileDialog.vue';import {request,today,label,displayTime} from './mobileApp';
export default{components:{MobileFilters,MobilePagination,MobileDialog},props:{options:Object},data:()=>({filters:{from:today(),to:today(),search:''},applied:null,items:[],pagination:null,loading:false,error:'',sequence:0,selected:null}),mounted(){this.load(1,true);},beforeUnmount(){this.sequence++;},methods:{label,time:displayTime,async load(page=1,apply=false){if(apply||!this.applied)this.applied={...this.filters};const sequence=++this.sequence;this.loading=true;this.error='';this.items=[];try{const data=await request(this,'get','activity',null,{...this.applied,page});if(sequence===this.sequence){this.items=data.items;this.pagination=data.pagination;}}catch(error){if(sequence===this.sequence){this.error=error.message;this.pagination=null;}}finally{if(sequence===this.sequence)this.loading=false;}}}};
</script>
